def compute_ranks(scores):
    order = np.argsort(-scores)
    ranks = np.empty_like(order, dtype=float)
    ranks[order] = np.arange(1, len(scores) + 1)
    return ranks


def compute_rrf(items, signals, k=RRF_K):
    n = len(items)
    if n == 0:
        return 0.0, np.zeros(0)
    rrf = np.zeros(n)
    for sig in signals:
